use kni_geometry_prototypes::*;
fn rect(w:f64)->Geometry{let p=|x,y|Point{x,y};Geometry{advance:w+2.,rings:vec![Ring{start:p(0.,0.),spans:vec![Span::Line(p(w,0.)),Span::Line(p(w,10.)),Span::Line(p(0.,10.)),Span::Line(p(0.,0.))]}]}}
#[test]fn rich_fixture_sections_and_streaming_identity(){let r=Rule{minimum_training:4,gauge_statistic:GaugeStatistic::Median,maximum_unique_training:512,coverage_numerator:1,coverage_denominator:2,flatten_fraction:1./1024.,bootstrap_replicates:4,stability_fraction:0.5};let mut xs=[2.,2.1,2.2,8.,8.1,8.2,40.].map(rect).to_vec();xs.push(xs[0].clone());let mut cubic=rect(3.);cubic.rings[0].spans[0]=Span::Cubic(Point{x:1.,y:0.},Point{x:2.,y:0.},Point{x:3.,y:0.});xs.push(cubic);let mut excluded=rect(4.);excluded.advance=f64::NAN;xs.push(excluded);let a=fit(&xs,r.clone(),&r.pin()).unwrap();assert!(a.available());let text=a.canonical_receipt().unwrap();let (bytes,lines,pin)=a.canonical_receipt_counted().unwrap();assert_eq!(bytes,text.len() as u64);assert_eq!(lines,text.bytes().filter(|b|*b==b'\n').count() as u64);assert_eq!(pin,hash(text.as_bytes()));assert_eq!(pin,a.pin());for section in ["diagnostics_no_selection_change\n","group=wall", "cluster ","member ","LOO ","prototype ","reason=unsupported_curve_type","reason=unclassifiable_singleton","alias_count=1", "input_occurrences=2"]{assert!(text.contains(section),"missing {section}");}assert!(a.training_assignments().iter().any(|x|x.unavailable_reason.as_deref()==Some("unclassifiable_singleton")));assert!(a.training_assignments().iter().filter(|x|x.unavailable_reason.is_some()).count()>=3);assert!(text.lines().filter(|l|l.starts_with("candidate ")).any(|l|l.split("excluded_index_runs=").nth(1).is_some_and(|v|!v.is_empty())));println!("rich_fixture bytes={bytes} lines={lines} artifact_pin={pin}");}
